23	    body {
24	      margin: 0;
25	      min-height: 100vh;
26	      color: var(--ink);
27	      background:
28	        radial-gradient(circle at 88% 5%, rgba(207, 222, 202, .7), transparent 24rem),
29	        var(--paper);
30	      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
31	    }
32	
33	    button, input { font: inherit; }
34	
35	    .shell {
36	      width: min(960px, calc(100% - 40px));
37	      margin: 0 auto;
38	      padding: 28px 0 80px;
39	    }
40	
41	    header {
42	      display: flex;
43	      justify-content: space-between;
44	      align-items: center;
45	      margin-bottom: 68px;
46	    }
47	
48	    .brand {
49	      display: inline-flex;
50	      align-items: center;
51	      gap: 10px;
52	      font-family: Georgia, "Times New Roman", serif;
53	      font-weight: 700;
54	      font-size: 22px;
55	      letter-spacing: -.02em;
56	    }
57	
58	    .mark {
59	      display: grid;
60	      place-items: center;
61	      width: 32px;
62	      height: 32px;
63	      color: white;
64	      background: var(--green);
65	      border-radius: 9px 9px 13px 9px;
66	      transform: rotate(-4deg);
67	    }
68	
69	    .mark span { transform: rotate(4deg); }
70	
71	    .prototype-label {
72	      color: var(--muted);
73	      font-size: 13px;
74	      letter-spacing: .08em;
75	      text-transform: uppercase;
76	    }
77	
78	    main { max-width: 760px; margin: 0 auto; }
79	
80	    .eyebrow {
81	      color: var(--green);
82	      font-size: 13px;
83	      font-weight: 750;
84	      letter-spacing: .1em;
85	      text-transform: uppercase;
86	      margin-bottom: 13px;
87	    }
88	
89	    h1 {
90	      max-width: 620px;
91	      margin: 0 0 12px;
92	      font-family: Georgia, "Times New Roman", serif;
93	      font-size: clamp(40px, 6vw, 64px);
94	      line-height: .98;
95	      letter-spacing: -.045em;
96	      font-weight: 500;
97	    }
98	
99	    .intro {
100	      margin: 0 0 38px;
101	      color: var(--muted);
102	      font-size: 17px;
103	      line-height: 1.55;
104	    }
105	
106	    .save-card {
107	      padding: 28px;
108	      background: var(--card);
109	      border: 1px solid rgba(222, 219, 209, .85);
110	      border-radius: 18px;
111	      box-shadow: var(--shadow);
112	    }
113	
114	    .form-row {
115	      display: grid;
116	      grid-template-columns: 1fr 1fr;
117	      gap: 16px;
118	    }
119	
120	    label {
121	      display: block;
122	      margin: 0 0 8px;
123	      font-size: 13px;
124	      font-weight: 720;
125	    }
126	
127	    input {
128	      width: 100%;
129	      height: 48px;
130	      padding: 0 14px;
131	      color: var(--ink);
132	      background: #fff;
133	      border: 1px solid var(--line);
134	      border-radius: 10px;
135	      outline: none;
136	      transition: border-color .15s, box-shadow .15s;
137	    }
138	
139	    input:focus {
140	      border-color: var(--green);
141	      box-shadow: 0 0 0 3px rgba(36, 91, 70, .12);
142	    }
143	
144	    input::placeholder { color: #9a9f9b; }
145	
146	    .actions {
147	      display: flex;
148	      align-items: center;
149	      justify-content: space-between;
150	      gap: 18px;
151	      margin-top: 20px;
152	    }
153	
154	    .hint { color: var(--muted); font-size: 13px; }
155	
156	    .save-button {
157	      min-width: 150px;
158	      height: 46px;
159	      padding: 0 20px;
160	      color: white;
161	      background: var(--green);
162	      border: 0;
163	      border-radius: 10px;
164	      font-weight: 720;
165	      cursor: pointer;
166	      box-shadow: 0 7px 16px rgba(36, 91, 70, .18);
167	    }
168	
169	    .save-button:hover { background: var(--green-dark); }
170	    .save-button:active { transform: translateY(1px); }
171	
172	    .error {
173	      min-height: 20px;
174	      margin: 12px 0 -8px;
175	      color: #9e3027;
176	      font-size: 13px;
177	    }
178	
179	    .collection { margin-top: 48px; }
180	
181	    .collection-head {
182	      display: flex;
183	      align-items: end;
184	      justify-content: space-between;
185	      padding-bottom: 14px;
186	      border-bottom: 1px solid var(--line);
187	    }
188	
189	    h2 {
190	      margin: 0;
191	      font-family: Georgia, "Times New Roman", serif;
192	      font-size: 25px;
193	      font-weight: 500;
194	      letter-spacing: -.02em;
195	    }
196	
197	    .count { color: var(--muted); font-size: 13px; }
198	
199	    .empty {
200	      padding: 36px 10px;
201	      color: var(--muted);
202	      text-align: center;
203	    }
204	
205	    .empty strong { display: block; color: var(--ink); margin-bottom: 5px; }
206	
207	    .bookmark {
208	      display: flex;
209	      gap: 16px;
210	      align-items: center;
211	      padding: 19px 4px;
212	      border-bottom: 1px solid var(--line);
213	      animation: arrive .28s ease-out;
214	    }
215	
216	    @keyframes arrive {
217	      from { opacity: 0; transform: translateY(8px); }
218	      to { opacity: 1; transform: translateY(0); }
219	    }
220	
221	    .favicon {
222	      flex: 0 0 auto;
223	      display: grid;
224	      place-items: center;
225	      width: 42px;
226	      height: 42px;
227	      color: var(--green);
228	      background: var(--mint);
229	      border-radius: 11px;
230	      font-family: Georgia, "Times New Roman", serif;
231	      font-size: 20px;
232	      font-weight: 700;
233	      text-transform: uppercase;
234	    }
235	
236	    .bookmark-copy { min-width: 0; flex: 1; }
237	
238	    .bookmark-title {
239	      display: block;
240	      overflow: hidden;
241	      color: var(--ink);
242	      font-weight: 720;
243	      text-decoration: none;
244	      text-overflow: ellipsis;
245	      white-space: nowrap;
246	    }
247	
248	    .bookmark-title:hover { color: var(--green); text-decoration: underline; }
249	
250	    .bookmark-url {
251	      display: block;
252	      overflow: hidden;
253	      margin-top: 4px;
254	      color: var(--muted);
255	      font-size: 13px;
256	      text-overflow: ellipsis;
257	      white-space: nowrap;
258	    }
259	
260	    .saved-note {
261	      color: var(--green);
262	      font-size: 13px;
263	      font-weight: 650;
264	    }
265	
266	    @media (max-width: 650px) {
267	      .shell { width: min(100% - 24px, 960px); padding-top: 18px; }
268	      header { margin-bottom: 48px; }
269	      .prototype-label { display: none; }
270	      .form-row { grid-template-columns: 1fr; }
271	      .save-card { padding: 20px; }
272	      .actions { align-items: stretch; flex-direction: column; }
273	      .save-button { width: 100%; }
274	      .bookmark { align-items: flex-start; }
275	      .saved-note { display: none; }
276	    }
277	  </style>
278	</head>
279	<body>
280	  <div class="shell" data-harness-ready="true">
281	    <header>
282	      <div class="brand"><span class="mark"><span>↘</span></span> Tuck</div>
283	      <div class="prototype-label">First-flow prototype</div>
284	    </header>
285	
286	    <main>
287	      <div class="eyebrow">Your bookmark home</div>
288	      <h1>Keep the good parts of the web.</h1>
289	      <p class="intro">Save useful links here, so the things worth remembering don't disappear into open tabs.</p>
290	
291	      <form class="save-card" id="save-form" novalidate>
292	        <div class="form-row">
293	          <div>
294	            <label for="url">Web address</label>
295	            <input id="url" name="url" type="url" placeholder="https://example.com/article" autocomplete="url" required>
296	          </div>
297	          <div>
298	            <label for="title">Title <span style="font-weight: 400; color: var(--muted)">(optional)</span></label>
299	            <input id="title" name="title" type="text" placeholder="What do you want to remember?" autocomplete="off">
300	          </div>
301	        </div>
302	        <div class="error" id="error" role="alert"></div>
303	        <div class="actions">
304	          <span class="hint">Your link will appear in the collection below.</span>
305	          <button class="save-button" type="submit">Save bookmark</button>
306	        </div>
307	      </form>
308	
309	      <section class="collection" aria-labelledby="collection-title">
310	        <div class="collection-head">
311	          <h2 id="collection-title">Saved links</h2>
312	          <span class="count" id="count">0 bookmarks</span>
313	        </div>
314	        <div id="bookmark-list">
315	          <div class="empty" id="empty"><strong>Nothing saved yet</strong>Your first useful link starts here.</div>
316	        </div>
317	      </section>
318	    </main>
319	  </div>
320	
321	  <script>
322	    const form = document.querySelector('#save-form');
323	    const urlInput = document.querySelector('#url');
324	    const titleInput = document.querySelector('#title');
325	    const list = document.querySelector('#bookmark-list');
326	    const error = document.querySelector('#error');
327	    const count = document.querySelector('#count');
328	    let total = 0;
329	
330	    form.addEventListener('submit', (event) => {
331	      event.preventDefault();
332	      error.textContent = '';
333	
334	      let parsed;
335	      try {
336	        parsed = new URL(urlInput.value.trim());
337	        if (!['http:', 'https:'].includes(parsed.protocol)) throw new Error('Unsupported address');
338	      } catch {
339	        error.textContent = 'Enter a complete web address, such as https://example.com';
340	        urlInput.focus();
341	        return;
342	      }
343	
344	      document.querySelector('#empty')?.remove();
345	      total += 1;
346	      const displayTitle = titleInput.value.trim() || parsed.hostname.replace(/^www\./, '');
347	      const item = document.createElement('article');
348	      item.className = 'bookmark';
349	
350	      const icon = document.createElement('div');
351	      icon.className = 'favicon';
352	      icon.textContent = displayTitle.charAt(0);
353	
354	      const copy = document.createElement('div');
355	      copy.className = 'bookmark-copy';
356	      const link = document.createElement('a');
357	      link.className = 'bookmark-title';
358	      link.href = parsed.href;
359	      link.target = '_blank';
360	      link.rel = 'noopener';
361	      link.textContent = displayTitle;
362	      const address = document.createElement('span');
363	      address.className = 'bookmark-url';
364	      address.textContent = parsed.href;
365	      copy.append(link, address);
366	
367	      const note = document.createElement('span');
368	      note.className = 'saved-note';
369	      note.textContent = 'Just saved';
370	      item.append(icon, copy, note);
371	      list.prepend(item);
372	
373	      count.textContent = `${total} ${total === 1 ? 'bookmark' : 'bookmarks'}`;
374	      form.reset();
375	      urlInput.focus();
376	    });
377	  </script>
378	</body>
379	</html>
