194	    document.querySelectorAll('.panel').forEach((panel) => {
195	      const mode = panel.dataset.mode;
196	      const items = panel.querySelector('.items');
197	      bookmarks.forEach(([icon, title, description, url]) => {
198	        const row = document.createElement('article');
199	        row.className = 'bookmark';
200	        row.dataset.title = title;
201	        row.innerHTML = `<span class="favicon">${icon}</span><div class="copy"><span class="title">${title}</span><span class="description">${description}</span><span class="url">${url}</span></div>`;
202	
203	        const remove = document.createElement('button');
204	        remove.type = 'button';
205	        remove.textContent = 'Remove';
206	        remove.setAttribute('aria-label', `Remove ${title}`);
207	        if (mode === 'direct') {
208	          remove.className = 'remove-direct';
209	          row.append(remove);
