211	          const details = document.createElement('details');
212	          const summary = document.createElement('summary');
213	          summary.setAttribute('aria-label', `Actions for ${title}`);
214	          summary.textContent = '•••';
215	          const menu = document.createElement('div');
216	          menu.className = 'menu';
217	          menu.append(remove);
218	          details.append(summary, menu);
219	          row.append(details);
220	        }
221	
222	        remove.addEventListener('click', () => {
223	          row.classList.add('removing');
224	          setTimeout(() => {
225	            row.remove();
226	            const remaining = items.querySelectorAll('.bookmark').length;
227	            panel.querySelector('.count').textContent = `${remaining} bookmarks`;
228	            panel.querySelector('.notice').textContent = `${title} was removed.`;
229	          }, 180);
230	        });
231	        items.append(row);
232	      });
233	    });
234	  </script>
