65	        <div class="panel-name">Choose labels</div>
66	        <div class="page-details"><span class="favicon">M</span><span><span class="page-title">HTML: HyperText Markup Language</span><span class="page-url">developer.mozilla.org/en-US/docs/Web/HTML</span></span></div>
67	        <div class="field"><label>Tags</label><div class="choices"><button class="choice" type="button" data-tag="work">work</button><button class="choice" type="button" data-tag="reading">reading</button><button class="choice" type="button" data-tag="recipes">recipes</button></div><button class="new-tag" type="button">+ Create another tag</button></div>
