73	  <script>
74	    document.querySelectorAll('.panel').forEach((panel) => {
75	      const tags = new Set();
76	      const renderResult = () => {
77	        const result = panel.querySelector('.result');
78	        result.innerHTML = `<div class="result-label">Saved bookmark</div><div class="result-title">HTML: HyperText Markup Language</div><div class="result-tags">${[...tags].map(tag => `<span class="chip">${tag}</span>`).join('')}</div>`;
79	      };
80	
81	      if (panel.dataset.mode === 'type') {
82	        const input = panel.querySelector('input');
83	        const chips = panel.querySelector('.chips');
84	        const renderChips = () => {
85	          chips.innerHTML = '';
86	          tags.forEach((tag) => {
87	            const chip = document.createElement('span');
88	            chip.className = 'chip';
89	            chip.append(document.createTextNode(tag));
90	            const remove = document.createElement('button');
91	            remove.type = 'button';
92	            remove.setAttribute('aria-label', `Remove ${tag} tag`);
93	            remove.textContent = '×';
94	            remove.addEventListener('click', () => { tags.delete(tag); renderChips(); });
95	            chip.append(remove);
96	            chips.append(chip);
97	          });
98	        };
99	        input.addEventListener('keydown', (event) => {
100	          if (event.key !== 'Enter' && event.key !== ',') return;
101	          event.preventDefault();
102	          const tag = input.value.trim().toLowerCase().replace(/,$/, '');
103	          if (tag) tags.add(tag);
104	          input.value = '';
105	          renderChips();
106	        });
107	      } else {
108	        panel.querySelectorAll('.choice').forEach((choice) => {
109	          choice.addEventListener('click', () => {
110	            const tag = choice.dataset.tag;
111	            if (tags.has(tag)) tags.delete(tag); else tags.add(tag);
112	            choice.classList.toggle('selected', tags.has(tag));
113	          });
114	        });
115	        panel.querySelector('.new-tag').addEventListener('click', () => {
116	          const name = prompt('Name the new tag');
117	          if (!name?.trim()) return;
118	          tags.add(name.trim().toLowerCase());
119	          const choice = document.createElement('button');
120	          choice.type = 'button';
121	          choice.className = 'choice selected';
122	          choice.dataset.tag = name.trim().toLowerCase();
123	          choice.textContent = name.trim().toLowerCase();
124	          panel.querySelector('.choices').append(choice);
125	        });
126	      }
127	
128	      panel.querySelector('.save').addEventListener('click', renderResult);
129	    });
130	  </script>
